const progressiveJPEGFixtureBase64 = ""

func progressiveJPEGFixture(t *testing.T) []byte {
	t.Helper()
	b, err := base64.StdEncoding.DecodeString(progressiveJPEGFixtureBase64)
	if err != nil { t.Fatal(err) }
	return b
}
